// Scope-aware book editing. These commands also work when typed in chat.
(()=>{
 const colorNames={brown:'#d4ae82',yellow:'#f8ed89',pink:'#efc2ee',purple:'#d6c4ea',green:'#d0edb8',blue:'#c6dff5',white:'#fffdf6'},nums={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10};
 const num=s=>nums[s?.toLowerCase()]||Number(s),number='(\\d+|one|two|three|four|five|six|seven|eight|nine|ten)';
 function pageList(raw){const text=raw.toLowerCase().replace(/\b(?:pages?|number)\b/g,' ').trim();if(!text||/^(?:this|current)$/.test(text))return[];const parts=text.split(/\s*(?:,|\band\b|&)\s*/).filter(Boolean),result=[];for(const part of parts){const range=part.trim().split(/\s+(?:to|through)\s+|\s*[-–]\s*/);if(range.length>2)return null;const start=num(range[0].trim()),end=range.length===2?num(range[1].trim()):start;if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end<start||end-start>1000)return null;for(let n=start;n<=end;n++)result.push(n)}return[...new Set(result)]}
 function parse(body){const text=body.trim().replace(/^please\s+/i,'').replace(/(?:\s+please)?[.!?]*$/i,'');let m;
  if(/^(?:undo(?: (?:the )?last (?:action|change|deletion))?|restore (?:the )?last deletion)$/i.test(text))return{kind:'undo'};
  if((m=/^(?:delete|clear|remove|erase)\s+(everything|all(?:\s+(?:the\s+)?(?:content|text|writing))?|(?:the\s+)?(?:current\s+)?(?:text|writing|content))\s+(?:from|on|in)\s+(?:this\s+|the\s+)?(?:current\s+|particular\s+)?pages?\b([\s\S]*)$/i.exec(text))){const pages=pageList(m[2]);return pages===null?{kind:'invalid-edit',message:'I could not identify the page numbers. Try “Delete everything on pages 1 and 2”.'}:{kind:/text|writing/i.test(m[1])?'clear-writing':'clear-content',scope:'page',pages}}
  if((m=/^(?:clear|erase)\s+(?:the\s+|this\s+)?(?:current\s+)?pages?\b([\s\S]*)$/i.exec(text))){const pages=pageList(m[1]);return pages===null?{kind:'invalid-edit',message:'Name the pages to clear, such as pages 1 and 2.'}:{kind:'clear-content',scope:'page',pages}}
  if(/^(?:delete|clear|remove|erase)\s+(?:everything|all (?:the )?content)(?:\s+(?:from|on|in))?\s+(?:this |the |my )?(?:whole |entire )?book$/i.test(text))return{kind:'clear-content',scope:'book'};
  if((m=/^(?:delete|remove|erase)\s+(?:this|that|it|this (?:sticky )?note|this (?:piece|item))(?:\s+(?:from|on|in)\s+(?:the )?page(?: number)?\s+([\w]+))?$/i.exec(text)))return{kind:'delete-target',page:m[1]?num(m[1]):null};
  if((m=/^(?:delete|remove|erase)\s+(?:from|on|in)\s+(?:the )?page(?: number)?\s+([\w]+)$/i.exec(text)))return{kind:'delete-target',page:num(m[1])};
  if((m=new RegExp('^(?:delete|clear|remove) (?:all )?(?:the )?(?:current )?(?:text|writing)(?: (?:from|on|in))? (?:this |the |my )?(?:whole |entire )?book$','i').exec(text)))return{kind:'clear-writing',scope:'book'};
  if((m=new RegExp('^(?:delete|clear|remove) (?:all )?(?:the )?(?:current )?(?:text|writing)(?: (?:from|on|in))? (?:this |the )?(?:current |particular )?page(?: (?:number )?'+number+')?$','i').exec(text)))return{kind:'clear-writing',scope:'page',page:m[1]?num(m[1]):null};
  if(/^(?:delete|clear|remove) (?:all )?(?:the )?(?:current )?(?:text|writing)$/i.test(text))return{kind:'clear-writing',scope:'unspecified'};
  if((m=/^(?:delete|remove) all (?:the )?sticky notes(?: (?:from|in|on) (?:this |the )?(whole book|book|current page|page|spread))?$/i.exec(text)))return{kind:'notes-all',scope:/book/i.test(m[1]||'')?'book':/page/i.test(m[1]||'')?'page':'spread'};
  if((m=new RegExp('^(delete|remove|select|duplicate|copy|move) (?:the |this |a )?(?:(brown|yellow|pink|purple|green|blue|white) )?sticky note(?: (?:number )?'+number+')?(?: to page (?:number )?'+number+')?$','i').exec(text)))return{kind:'note-control',verb:m[1].toLowerCase(),color:m[2]?.toLowerCase(),number:m[3]?num(m[3]):null,page:m[4]?num(m[4]):null};
  if(/^book controls$/i.test(text))return{kind:'book-controls'};
  return null;
 }
 const pageForPiece=p=>(Number(p.x)||0)+(Number(p.w)||0)/2<50?'left':'right';
 const currentPage=()=>activeBook().activeSpread*2+(window.diaryDictationTarget.capture().element.id==='diary-right'?2:window.diaryDictationTarget.capture().element.id==='diary-left'?1:pageForPiece(pieces.find(p=>p.id===selected)||{})==='right'?2:1);
 function matchNote(action){const notes=pieces.filter(p=>p.type==='note');if(action.number)return notes[action.number-1]||null;const matching=action.color?notes.filter(p=>p.color.toLowerCase()===colorNames[action.color]):notes;const chosen=matching.find(p=>p.id===selected);return chosen|| (matching.length===1?matching[0]:matching.length>1?'ambiguous':null)}
 const snapshot=()=>{persistLibrary();return structuredClone(activeBook())};
 function refresh(){const spread=ensureSpreads(activeBook());diary=structuredClone(spread.diary);pieces=structuredClone(spread.pieces||[]);entries=activeBook().entries||[];entryId=spread.entryId||null;selectPiece(null);renderDiary();renderPieces();bookLabels();return saveDraft()}
 function syncEntries(book){for(const entry of book.entries||[]){const spread=book.spreads.find(s=>s.id===entry.spreadId);if(!spread)continue;entry.diary=structuredClone(spread.diary);entry.pieces=structuredClone(spread.pieces);entry.text=[spread.diary.left,spread.diary.right,...spread.pieces.map(p=>p.text)].filter(Boolean).join('\n\n');entry.title=entry.text.split('\n')[0]?.slice(0,65)||spread.heading||'Untitled entry'}}
 function record(before,label){syncEntries(activeBook());const saved=refresh();return{message:label+(saved?' Say “Undo” to restore it.':' Changes are visible but could not be saved; download a backup.'),undo:{bookEdit:true,book:before.id,before,after:structuredClone(activeBook())}}}
 function apply(action){if(!requireBookEdit())return{message:activeBook().isSample?'The sample is read-only. Make your own book to edit.':'Sign in to edit your books.'};
  if(action.kind==='invalid-edit')return{message:action.message};
  if(action.kind==='delete-target'){const piece=pieces.find(p=>p.id===selected);if(!piece)return{message:'Select the item to remove, or say “Delete everything on page '+(action.page||currentPage())+'”. Nothing was changed.'};const page=activeBook().activeSpread*2+(pageForPiece(piece)==='left'?1:2);if(action.page!==null&&(!Number.isInteger(action.page)||action.page!==page))return{message:'The selected item is on page '+page+'. Say “Delete this” to remove it, or select an item on the requested page.'};const before=snapshot();ensureSpreads(activeBook()).pieces=ensureSpreads(activeBook()).pieces.filter(p=>p.id!==piece.id);return record(before,'Removed the selected item from page '+page+'.')}
  if(action.kind==='clear-writing'||action.kind==='clear-content'){
   if(action.scope==='unspecified')return{message:'Which writing? Say “Clear text from the current page” or “Clear all text from this book”.'};
   const book=activeBook(),numbers=action.pages?.length?action.pages:[action.page||currentPage()],invalid=numbers.find(n=>!Number.isInteger(n)||n<1||n>book.spreads.length*2);if(action.scope==='page'&&invalid!==undefined)return{message:'Page '+invalid+' does not exist. Nothing was changed.'};
   const all=action.kind==='clear-content',targets=new Set(numbers),before=snapshot();for(let i=0;i<book.spreads.length;i++){const spread=book.spreads[i];for(const side of ['left','right'])if(action.scope==='book'||targets.has(i*2+(side==='left'?1:2))){spread.diary[side]='';if(all){spread.pieces=spread.pieces.filter(piece=>pageForPiece(piece)!==side);if(side==='left')spread.heading=''}else for(const piece of spread.pieces)if(pageForPiece(piece)===side)piece.text=''}}
   const area=action.scope==='book'?'this whole book':(numbers.length>1?'pages ':'page ')+numbers.join(' and ');return record(before,all?'Removed writing, notes, and media from '+area+'. The book and its pages are kept.':'Cleared writing, note text, and captions on '+area+'. The pages and media are kept.');
  }
  if(action.kind==='notes-all'){const before=snapshot(),number=currentPage();let count=0;for(let i=0;i<activeBook().spreads.length;i++){if(action.scope!=='book'&&i!==activeBook().activeSpread)continue;const spread=activeBook().spreads[i];spread.pieces=spread.pieces.filter(p=>{const remove=p.type==='note'&&(action.scope!=='page'||i*2+(pageForPiece(p)==='left'?1:2)===number);if(remove)count++;return!remove})}if(!count)return{message:'There are no sticky notes in that area.'};return record(before,'Removed '+count+' sticky '+(count===1?'note':'notes')+' from '+(action.scope==='book'?'this book':action.scope==='page'?'page '+number:'these pages')+'.')}
  if(action.kind==='note-control'){
   const piece=matchNote(action);if(piece==='ambiguous')return{message:'There is more than one matching sticky note. Say “Select sticky note 2”, then try again.'};if(!piece)return{message:'No matching sticky note is on these pages. Try another color or note number.'};
   if(action.verb==='select'){selectPiece(piece.id);return{message:'Selected the sticky note. You can dictate, move, recolor, or delete it.'}};
   const before=snapshot(),spread=ensureSpreads(activeBook());
   if(action.verb==='delete'||action.verb==='remove')spread.pieces=spread.pieces.filter(p=>p.id!==piece.id);
   else if(action.verb==='duplicate'||action.verb==='copy'){const copy=structuredClone(piece);copy.id=crypto.randomUUID();copy.x=Math.min(75,copy.x+5);copy.y=Math.min(75,copy.y+5);spread.pieces.push(copy)}
   else if(action.verb==='move'){if(!action.page||action.page<1||action.page>activeBook().spreads.length*2)return{message:'Name an existing destination, such as “Move sticky note 1 to page 4”.'};spread.pieces=spread.pieces.filter(p=>p.id!==piece.id);const copy=structuredClone(piece);copy.x=action.page%2?8:57;copy.y=15;activeBook().spreads[Math.floor((action.page-1)/2)].pieces.push(copy)}
   return record(before,action.verb==='move'?'Moved the sticky note to page '+action.page+'.':action.verb==='copy'||action.verb==='duplicate'?'Duplicated the sticky note.':'Removed the sticky note.');
  }
  return null;
 }
 function undo(change){if(!requireBookEdit())return false;if(activeBook().id!==change.book)return false;persistLibrary();const comparable=book=>{const copy=structuredClone(book);delete copy.updated;delete copy.activeSpread;delete copy.draft;return JSON.stringify(copy)};if(comparable(activeBook())!==comparable(change.after))return false;const current=activeBook().activeSpread;Object.assign(activeBook(),structuredClone(change.before));activeBook().activeSpread=Math.min(current,activeBook().spreads.length-1);refresh();return true}
 window.bookControls={parse,apply,undo,currentPage};
})();
